class Solution {
    public long countBadPairs(int[] nums){
        Map<Integer,Integer> frequency=new HashMap<>();
        long answer=0;
        for(int index=0;index<nums.length;index++){
            int key=nums[index]-index;
            answer+=index-frequency.getOrDefault(key,0);
            frequency.merge(key,1,Integer::sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countBadPairs(nums:IntArray):Long{
        val frequency=HashMap<Int,Int>();
        var answer=0L;
        for(index in nums.indices){
            val key=nums[index]-index;
            answer+=index-(frequency[key]?:0);
            frequency[key]=(frequency[key]?:0)+1
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:long long countBadPairs(vector<int>& nums){
        unordered_map<int,int> frequency;
        long long answer=0;
        for(int index=0;index<(int)nums.size();++index){
            int key=nums[index]-index;
            answer+=index-frequency[key];
            ++frequency[key];
        }
        return answer;
    }
};
